def _ram_names():
    names = {}
    for a, (n, size, _s, _d) in RAM_DEFS.items():
        names[a] = n
        for k in range(1, size):
            names.setdefault(a + k, '%s+%d' % (n, k))
    return names


RAM = _ram_names()
